/** 成绩中心第一交付切片：仅允许 MANUAL 成绩项目，所有状态转换在事务内完成。 */
@Service
public class GradeCenterService {
 private final AssessmentSchemeRepository schemes; private final AssessmentComponentRepository components; private final GradebookRepository gradebooks; private final GradebookStudentRepository students; private final GradeItemRepository items; private final CourseGradeRepository courseGrades; private final GradePublishSnapshotRepository snapshots; private final GradeCorrectionRepository corrections; private final CourseOfferingRepository offerings; private final TeachingClassMemberRepository members; private final StudentProfileRepository profiles; private final SubjectRepository subjects; private final WorkflowService workflows; private final IWorkflowTaskRepository workflowTasks; private final IWorkflowInstanceRepository workflowInstances; private final EducationDataScopeService dataScopes; private final GradeNotificationService notifications; private final IAuditLogService audit; private final ObjectMapper json; private final DomainEventOutboxService domainEvents; private final EducationDomainEventService educationEvents; private final GradeRuleEvaluationService ruleEvaluation;
 public GradeCenterService(AssessmentSchemeRepository schemes,AssessmentComponentRepository components,GradebookRepository gradebooks,GradebookStudentRepository students,GradeItemRepository items,CourseGradeRepository courseGrades,GradePublishSnapshotRepository snapshots,GradeCorrectionRepository corrections,CourseOfferingRepository offerings,TeachingClassMemberRepository members,StudentProfileRepository profiles,SubjectRepository subjects,WorkflowService workflows,IWorkflowTaskRepository workflowTasks,IWorkflowInstanceRepository workflowInstances,EducationDataScopeService dataScopes,GradeNotificationService notifications,IAuditLogService audit,ObjectMapper json,DomainEventOutboxService domainEvents,EducationDomainEventService educationEvents,GradeRuleEvaluationService ruleEvaluation){this.schemes=schemes;this.components=components;this.gradebooks=gradebooks;this.students=students;this.items=items;this.courseGrades=courseGrades;this.snapshots=snapshots;this.corrections=corrections;this.offerings=offerings;this.members=members;this.profiles=profiles;this.subjects=subjects;this.workflows=workflows;this.workflowTasks=workflowTasks;this.workflowInstances=workflowInstances;this.dataScopes=dataScopes;this.notifications=notifications;this.audit=audit;this.json=json;this.domainEvents=domainEvents;this.educationEvents=educationEvents;this.ruleEvaluation=ruleEvaluation;}
 @Transactional(readOnly=true) public List<AssessmentScheme> listSchemes(String offeringId){return offeringId==null?schemes.findAll():schemes.findByOfferingIdOrderByCreateTimeDesc(offeringId);}
 @Transactional(readOnly=true) public List<Gradebook> listGradebooks(String actor){return dataScopes.resolve(actor).teacherIds().stream().flatMap(id->gradebooks.findByTeacherIdOrderByCreateTimeDesc(id).stream()).toList();}
 @Transactional public AssessmentScheme createScheme(SchemeCommand c,String actor){validateScheme(c); CourseOffering o=authorizedOffering(c.offeringId(),actor); AssessmentScheme s=new AssessmentScheme(); s.setSchoolId(serverSchoolId(actor));s.setOfferingId(o.getId());s.setName(c.name());s.setTotalScore(c.totalScore());s.setPassScore(c.passScore());s.setStatus("DRAFT");s=schemes.save(s); int order=0; for(ComponentCommand x:c.components()){AssessmentComponent a=new AssessmentComponent();a.setSchemeId(s.getId());a.setCode(x.code());a.setName(x.name());a.setSourceType(x.sourceType());a.setWeight(x.weight());a.setMaxScore(x.maxScore());a.setSortOrder(x.sortOrder()==null?order++:x.sortOrder());components.save(a);} audit.log(actor,"EDU_GRADE_SCHEME_CREATE","schemeId="+s.getId()); return s;}
 @Transactional public AssessmentScheme publishScheme(String id,String actor){AssessmentScheme s=schemes.findById(id).orElseThrow(); authorizedOffering(s.getOfferingId(),actor); validateWeights(components.findBySchemeIdOrderBySortOrder(id)); s.setStatus("PUBLISHED");s.setPublishedVersionNo(1); audit.log(actor,"EDU_GRADE_SCHEME_PUBLISH","schemeId="+id);return schemes.save(s);}
 @Transactional public AssessmentScheme updateScheme(String id,SchemeCommand c,String actor){AssessmentScheme s=schemes.findById(id).orElseThrow();authorizedOffering(s.getOfferingId(),actor);if(!"DRAFT".equals(s.getStatus()))throw new IllegalStateException("仅草稿方案可修改");if(c.rowVersion()!=null&&!c.rowVersion().equals(s.getRowVersion()))throw new org.springframework.orm.ObjectOptimisticLockingFailureException(AssessmentScheme.class,id);validateScheme(c);s.setName(c.name());s.setTotalScore(c.totalScore());s.setPassScore(c.passScore());components.deleteBySchemeId(id);int order=0;for(ComponentCommand x:c.components()){AssessmentComponent a=new AssessmentComponent();a.setSchemeId(id);a.setCode(x.code());a.setName(x.name());a.setSourceType(x.sourceType());a.setWeight(x.weight());a.setMaxScore(x.maxScore());a.setSortOrder(x.sortOrder()==null?order++:x.sortOrder());components.save(a);}audit.log(actor,"EDU_GRADE_SCHEME_UPDATE","schemeId="+id);return schemes.save(s);}
 @Transactional public Gradebook createGradebook(GradebookCommand c,String actor){CourseOffering o=authorizedOffering(c.offeringId(),actor);AssessmentScheme s=schemes.findById(c.schemeId()).orElseThrow();if(!"PUBLISHED".equals(s.getStatus())||!s.getOfferingId().equals(o.getId()))throw new IllegalArgumentException("只能使用本课程已发布方案");if(gradebooks.findByOfferingIdAndSchemeId(c.offeringId(),c.schemeId()).isPresent())throw new IllegalStateException("该课程已有成绩册");Gradebook g=new Gradebook();g.setSchoolId(serverSchoolId(actor));g.setOfferingId(o.getId());g.setSchemeId(s.getId());g.setTeacherId(o.getTeacherId());g.setStatus("EDITING");g=gradebooks.save(g);for(TeachingClassMember m:members.findByOfferingIdAndEnrollmentStatus(o.getId(),"ENROLLED")){var p=profiles.findById(m.getStudentId()).orElse(null);if(p==null)continue;GradebookStudent gs=new GradebookStudent();gs.setGradebookId(g.getId());gs.setStudentId(p.getId());gs.setStudentNo(p.getStudentNo());gs.setStudentName(p.getStudentName());gs.setAdministrativeClassId(p.getAdministrativeClassId());gs.setEnrollmentStatus(m.getEnrollmentStatus());gs.setSourceMemberId(m.getId());gs.setEnrolledAt(m.getEnrolledAt());gs.setWithdrawnAt(m.getWithdrawnAt());gs.setSnapshotHash(hash(snapshotStudent(gs)));students.save(gs);}audit.log(actor,"EDU_GRADEBOOK_CREATE","gradebookId="+g.getId());return g;}
 @Transactional(readOnly=true) public GradebookDetailResponse getGradebook(String id,String actor){Gradebook g=authorizedGradebook(id,actor);List<StudentSnapshot> studentSnapshots=students.findByGradebookId(id).stream().map(s->new StudentSnapshot(s.getId(),s.getStudentId(),s.getStudentNo(),s.getStudentName(),s.getAdministrativeClassId(),s.getEnrollmentStatus(),s.getSourceMemberId(),s.getEnrolledAt(),s.getWithdrawnAt(),s.getSnapshotVersion(),s.getSnapshotHash())).toList();List<ComponentDetail> componentDetails=components.findBySchemeIdOrderBySortOrder(g.getSchemeId()).stream().map(c->new ComponentDetail(c.getId(),c.getCode(),c.getName(),c.getSourceType(),c.getWeight(),c.getMaxScore(),c.getSortOrder())).toList();List<GradeItemDetail> itemDetails=items.findByGradebookId(id).stream().map(i->new GradeItemDetail(i.getId(),i.getComponentId(),i.getStudentId(),i.getRawScore(),i.getConvertedScore(),i.getSpecialStatus(),i.getRemark(),i.getRowVersion())).toList();List<SnapshotMetadata> snapshotMetadata=snapshots.findByGradebookIdOrderByVersionNoDesc(id).stream().map(s->new SnapshotMetadata(s.getVersionNo(),s.getSnapshotHash(),s.getPublishedBy(),s.getPublishedAt())).toList();return new GradebookDetailResponse(g.getId(),g.getOfferingId(),g.getSchemeId(),g.getStatus(),g.getSubmissionNo(),g.getRowVersion(),g.getSubmittedAt(),g.getPublishedAt(),studentSnapshots,componentDetails,itemDetails,snapshotMetadata);}
 @Transactional(readOnly=true) public List<GradePublishSnapshot> snapshots(String id,String actor){authorizedGradebook(id,actor);return snapshots.findByGradebookIdOrderByVersionNoDesc(id);}
 @Transactional public Gradebook saveItems(String id,ItemsCommand command,String actor){Gradebook g=authorizedGradebook(id,actor);if(!Set.of("EDITING","REJECTED").contains(g.getStatus()))throw new IllegalStateException("当前状态不可录入");if(command.rowVersion()!=null&&!command.rowVersion().equals(g.getRowVersion()))throw new org.springframework.orm.ObjectOptimisticLockingFailureException(Gradebook.class,id);List<AssessmentComponent> allowed=components.findBySchemeIdOrderBySortOrder(g.getSchemeId());Map<String,AssessmentComponent> byId=allowed.stream().collect(Collectors.toMap(AssessmentComponent::getId,x->x));List<GradebookStudent> roster=students.findByGradebookId(id);for(GradeItemCommand c:command.items()){AssessmentComponent component=byId.get(c.componentId());if(component==null)throw new IllegalArgumentException("成绩项目不属于当前成绩册方案");if(c.rawScore()!=null&&(c.rawScore().signum()<0||c.rawScore().compareTo(component.getMaxScore())>0))throw new IllegalArgumentException("成绩超出项目满分");if(roster.stream().noneMatch(x->x.getStudentId().equals(c.studentId())))throw new IllegalArgumentException("学生不在成绩册快照");GradeItem item=items.findByGradebookId(id).stream().filter(x->x.getComponentId().equals(c.componentId())&&x.getStudentId().equals(c.studentId())).findFirst().orElseGet(GradeItem::new);item.setGradebookId(id);item.setComponentId(c.componentId());item.setStudentId(c.studentId());item.setRawScore(c.rawScore());item.setConvertedScore(c.rawScore());item.setSpecialStatus(c.specialStatus());item.setRemark(c.remark());items.save(item);}return gradebooks.saveAndFlush(g);}
 @Transactional public Gradebook submit(String id,String actor){Gradebook g=authorizedGradebook(id,actor);if(!Set.of("EDITING","REJECTED").contains(g.getStatus()))throw new IllegalStateException("成绩册不可提交");if(items.findByGradebookId(id).isEmpty())throw new IllegalArgumentException("请先录入成绩");g.setSubmissionNo(g.getSubmissionNo()+1);g.setSubmittedAt(LocalDateTime.now());g.setStatus("REVIEWING");var instance=workflows.startByCode("EDU_GRADEBOOK_REVIEW",id,Map.<String,Object>of("gradebookId",id,"submitter",actor),actor);g.setWorkflowInstanceId(instance.getId());audit.log(actor,"EDU_GRADEBOOK_SUBMIT","gradebookId="+id);return gradebooks.save(g);}
 @Transactional public Gradebook review(String id,String taskId,boolean approved,String comment,String actor){Gradebook g=gradebooks.findById(id).orElseThrow(()->new IllegalArgumentException("成绩册不存在"));WorkflowTask task=workflowTasks.findById(taskId).orElseThrow(()->new IllegalArgumentException("审核任务不存在"));if(!id.equals(workflows.instance(task.getInstanceId()).getBusinessKey()))throw new AccessDeniedException("审核任务不属于当前成绩册");if(dataScopes.resolve(actor).teacherIds().contains(g.getTeacherId()))throw new AccessDeniedException("提交人不得审核本人成绩册");var instance=approved?workflows.completeTask(taskId,true,comment,actor):workflows.rejectTask(taskId,"",comment,actor);if("COMPLETED".equals(instance.getStatus()))g.setStatus("APPROVED");else if("REJECTED".equals(instance.getStatus()))g.setStatus("REJECTED");else g.setStatus("REVIEWING");audit.log(actor,approved?"EDU_GRADEBOOK_APPROVE":"EDU_GRADEBOOK_REJECT","gradebookId="+id+",node="+task.getNodeKey());return gradebooks.save(g);}
 @Transactional public Gradebook publish(String id,String actor){Gradebook g=gradebooks.findById(id).orElseThrow(()->new IllegalArgumentException("成绩册不存在"));if("PUBLISHED".equals(g.getStatus()))return g;if(!"APPROVED".equals(g.getStatus()))throw new IllegalStateException("仅审核通过后可发布");List<GradebookStudent> ss=students.findByGradebookId(id);List<AssessmentComponent> cs=components.findBySchemeIdOrderBySortOrder(g.getSchemeId());Map<String,List<GradeItem>> by=items.findByGradebookId(id).stream().collect(Collectors.groupingBy(GradeItem::getStudentId));Map<String,AssessmentComponent> componentById=cs.stream().collect(Collectors.toMap(AssessmentComponent::getId,x->x));AssessmentScheme scheme=schemes.findById(g.getSchemeId()).orElseThrow();CourseOffering offering=offerings.findById(g.getOfferingId()).orElseThrow();int version=g.getSubmissionNo();GradeRuleEvaluationService.Evaluation rule=ruleEvaluation==null?GradeRuleEvaluationService.platformDefault(BigDecimal.ZERO):ruleEvaluation.describe(scheme.getGradeRuleSetId());Map<String,Object> snapshotData=new LinkedHashMap<>();snapshotData.put("snapshotVersion",1);snapshotData.put("capturedAt",LocalDateTime.now().toString());snapshotData.put("gradeRuleSetId",rule.ruleSetId());snapshotData.put("gradeRuleVersionNo",rule.ruleSetVersion());snapshotData.put("gradeRuleSnapshot",rule.ruleSnapshotJson());Map<String,Object> offeringSnapshot=new LinkedHashMap<>();offeringSnapshot.put("id",offering.getId());offeringSnapshot.put("offeringCode",offering.getOfferingCode());offeringSnapshot.put("teachingClassName",offering.getTeachingClassName());offeringSnapshot.put("semesterCode",offering.getSemesterCode());offeringSnapshot.put("courseCode",offering.getCourseCode());offeringSnapshot.put("courseName",offering.getCourseName());offeringSnapshot.put("campusId",offering.getCampusId());offeringSnapshot.put("offeringMode",offering.getOfferingMode());snapshotData.put("offering",offeringSnapshot);snapshotData.put("students",ss.stream().map(this::snapshotStudent).toList());String snapshot;try{snapshot=json.writeValueAsString(snapshotData);}catch(Exception e){throw new IllegalArgumentException("成绩快照序列化失败",e);}String hash=hash(snapshot);for(GradebookStudent student:ss){BigDecimal total=by.getOrDefault(student.getStudentId(),List.of()).stream().filter(x->x.getConvertedScore()!=null).map(x->{AssessmentComponent c=componentById.get(x.getComponentId());return c==null?BigDecimal.ZERO:x.getConvertedScore().divide(c.getMaxScore(),8,java.math.RoundingMode.HALF_UP).multiply(c.getWeight());}).reduce(BigDecimal.ZERO,BigDecimal::add);CourseGrade cg=new CourseGrade();cg.setGradebookId(id);cg.setStudentId(student.getStudentId());cg.setTotalScore(total);GradeRuleEvaluationService.Evaluation evaluation=ruleEvaluation==null?GradeRuleEvaluationService.platformDefault(total):ruleEvaluation.evaluate(total,scheme.getGradeRuleSetId());cg.setGradeLevel(evaluation.gradeLevel());cg.setGradePoint(evaluation.gradePoint());cg.setPassed(evaluation.passed());cg.setGradeRuleSetId(evaluation.ruleSetId());cg.setGradeRuleVersionNo(evaluation.ruleSetVersion());cg.setGradeRuleSnapshotJson(evaluation.ruleSnapshotJson());cg.setVersionNo(version);cg.setSnapshotHash(hash);courseGrades.save(cg);notifications.published(id,student.getStudentId(),g.getOfferingId(),String.valueOf(version));}GradePublishSnapshot p=new GradePublishSnapshot();p.setGradebookId(id);p.setVersionNo(version);p.setSnapshotJson(snapshot);p.setSnapshotHash(hash);p.setGradeRuleSetId(rule.ruleSetId());p.setGradeRuleVersionNo(rule.ruleSetVersion());p.setGradeRuleSnapshotJson(rule.ruleSnapshotJson());p.setPublishedBy(actor);p.setPublishedAt(LocalDateTime.now());snapshots.save(p);g.setStatus("PUBLISHED");g.setPublishedAt(LocalDateTime.now());audit.log(actor,"EDU_GRADEBOOK_PUBLISH","gradebookId="+id+",version="+version);Gradebook saved=gradebooks.save(g);var event=new com.chronos.education.grade.dto.GradeSourceEventContracts.CourseGradesPublishedV1(UUID.randomUUID().toString(),"CourseGradesPublishedV1",java.time.OffsetDateTime.now(),1,g.getId(),g.getOfferingId(),g.getSubmissionNo(),hash,actor);domainEvents.enqueue(event);if(educationEvents!=null)educationEvents.enqueueGradeEvent(event.eventType(),g.getId(),event.eventId(),event,actor);return saved;}
 @Transactional(readOnly=true) public List<CourseGrade> studentGrades(String studentId){return courseGrades.findByStudentIdOrderByVersionNoDesc(studentId).stream().filter(g->gradebooks.findById(g.getGradebookId()).map(x->"PUBLISHED".equals(x.getStatus())).orElse(false)).toList();}
 @Transactional(readOnly=true) public CourseGrade studentGrade(String id,String studentId){return studentGrades(studentId).stream().filter(g->g.getId().equals(id)).findFirst().orElseThrow(()->new org.springframework.security.access.AccessDeniedException("成绩不存在或尚未发布"));}
 @Transactional(readOnly=true) public AnalysisCapability analysisCapability(String dimension){if("knowledge".equals(dimension))return new AnalysisCapability(dimension,false,"UNAVAILABLE","当前发布成绩模型没有真实知识点关联，已安全关闭该维度",List.of("题目/成绩项目知识点关联"));return new AnalysisCapability(dimension,true,"SUPPORTED","基于已发布成绩快照的只读聚合",List.of("PUBLISHED 成绩册","GradePublishSnapshot","EducationDataScopeService 数据范围过滤"));}
 @Transactional(readOnly=true) public AnalysisResult analysis(String dimension,String actor){AnalysisCapability base=analysisCapability(dimension);if(!base.supported())return new AnalysisResult(base.dimension(),false,base.status(),base.reason(),base.dependencies(),List.of());EducationDataScope scope=dataScopes.resolve(actor);Map<String,Aggregate> grouped=new LinkedHashMap<>();Map<String,Subject> subjectByCode=subjects.findAll().stream().collect(Collectors.toMap(Subject::getSubjectCode,x->x,(a,b)->a));for(Gradebook book:gradebooks.findByStatusOrderByPublishedAtDesc("PUBLISHED")){Integer version=book.getSubmissionNo();if(version==null||snapshots.findByGradebookIdAndVersionNo(book.getId(),version).isEmpty())continue;CourseOffering offering=offerings.findById(book.getOfferingId()).orElse(null);if(offering==null||(!scope.fullAccess()&&!dataScopes.canAccessOffering(scope,offering)))continue;Subject subject=subjectByCode.get(offering.getCourseCode());if("subject".equals(dimension)&&subject==null)continue;Map<String,GradebookStudent> roster=students.findByGradebookId(book.getId()).stream().collect(Collectors.toMap(GradebookStudent::getStudentId,x->x,(a,b)->a));for(CourseGrade grade:courseGrades.findByGradebookIdAndVersionNo(book.getId(),version)){if(grade.getTotalScore()==null)continue;GradebookStudent student=roster.get(grade.getStudentId());String key=analysisKey(dimension,student,offering,subject);if(key==null)continue;String label="subject".equals(dimension)?subject.getSubjectName():key;Aggregate aggregate=grouped.computeIfAbsent(key,k->new Aggregate(label,"trend".equals(dimension)?offering.getSemesterCode():null));aggregate.add(grade);}}List<AnalysisRow> rows=grouped.entrySet().stream().map(e->e.getValue().row(e.getKey())).toList();if(rows.isEmpty())return new AnalysisResult(dimension,false,"UNAVAILABLE","当前数据范围内没有具备完整真实维度字段的已发布成绩",base.dependencies(),List.of());return new AnalysisResult(dimension,true,"SUPPORTED",base.reason(),base.dependencies(),rows);}
 private String analysisKey(String dimension,GradebookStudent student,CourseOffering offering,Subject subject){if("trend".equals(dimension))return offering.getSemesterCode();if(student==null)return null;if("class".equals(dimension))return blank(student.getAdministrativeClassId())?null:student.getAdministrativeClassId();if("grade".equals(dimension)){StudentProfile profile=profiles.findById(student.getStudentId()).orElse(null);return profile==null||blank(profile.getGradeId())?null:profile.getGradeId();}if("subject".equals(dimension))return subject==null?null:subject.getSubjectCode();return null;}
 private boolean blank(String value){return value==null||value.isBlank();}
 private static final class Aggregate {private final String label;private final String period;private final Set<String> students=new HashSet<>();private long graded;private long passed;private BigDecimal total=BigDecimal.ZERO;private Aggregate(String label,String period){this.label=label;this.period=period;}private void add(CourseGrade grade){students.add(grade.getStudentId());graded++;if(Boolean.TRUE.equals(grade.getPassed()))passed++;total=total.add(grade.getTotalScore());}private AnalysisRow row(String key){BigDecimal average=graded==0?BigDecimal.ZERO:total.divide(BigDecimal.valueOf(graded),2,java.math.RoundingMode.HALF_UP);BigDecimal passRate=graded==0?BigDecimal.ZERO:BigDecimal.valueOf(passed*100.0/graded).setScale(2,java.math.RoundingMode.HALF_UP);return new AnalysisRow(key,label,students.size(),graded,passed,average,passRate,period);}}
 @Transactional public ImportResult importItems(String id, MultipartFile file, String actor) {
  Gradebook g=authorizedGradebook(id,actor); if(!Set.of("EDITING","REJECTED").contains(g.getStatus())) throw new IllegalStateException("当前状态不可导入");
  if(file==null||file.isEmpty()) throw new IllegalArgumentException("请选择Excel文件"); if(file.getSize()>10*1024*1024) throw new IllegalArgumentException("文件不能超过10MB");
  List<GradebookStudent> roster=students.findByGradebookId(id); Map<String,GradebookStudent> byNo=roster.stream().collect(Collectors.toMap(GradebookStudent::getStudentNo,x->x,(a,b)->a));
  Map<String,AssessmentComponent> byCode=components.findBySchemeIdOrderBySortOrder(g.getSchemeId()).stream().collect(Collectors.toMap(AssessmentComponent::getCode,x->x,(a,b)->a));
  List<GradeItemCommand> valid=new ArrayList<>(); List<ImportRowError> errors=new ArrayList<>(); int total=0;
  try(Workbook workbook=WorkbookFactory.create(new ByteArrayInputStream(file.getBytes()))) {
   if(workbook.getNumberOfSheets()==0) throw new IllegalArgumentException("Excel没有工作表");
   Sheet sheet=workbook.getSheetAt(0); Row header=sheet.getRow(0); if(header==null) throw new IllegalArgumentException("缺少表头");
   DataFormatter formatter=new DataFormatter(); Map<Integer,AssessmentComponent> columns=new LinkedHashMap<>(); Set<String> seen=new HashSet<>();
   for(int c=1;c<header.getLastCellNum();c++){String code=formatter.formatCellValue(header.getCell(c)).trim(); if(code.isBlank()) continue; AssessmentComponent component=byCode.get(code); if(component==null) throw new IllegalArgumentException("未知成绩项目编码："+code); if(!seen.add(code)) throw new IllegalArgumentException("成绩项目编码重复："+code); columns.put(c,component);}
   if(columns.isEmpty()||!"studentNo".equalsIgnoreCase(formatter.formatCellValue(header.getCell(0)).trim())) throw new IllegalArgumentException("第一列表头必须为studentNo且至少包含一个成绩项目");
   for(int r=1;r<=sheet.getLastRowNum();r++){Row row=sheet.getRow(r); if(row==null) continue; total++; String studentNo=formatter.formatCellValue(row.getCell(0)).trim(); GradebookStudent student=byNo.get(studentNo);
    if(student==null){errors.add(new ImportRowError(r+1,studentNo,"","学号不在成绩册快照中"));continue;}
    for(Map.Entry<Integer,AssessmentComponent> entry:columns.entrySet()){String text=formatter.formatCellValue(row.getCell(entry.getKey())).trim(); if(text.isBlank()){errors.add(new ImportRowError(r+1,studentNo,entry.getValue().getCode(),"成绩不能为空"));continue;} try{BigDecimal score=new BigDecimal(text); if(score.signum()<0||score.compareTo(entry.getValue().getMaxScore())>0) throw new IllegalArgumentException("成绩超出满分"); valid.add(new GradeItemCommand(entry.getValue().getId(),student.getStudentId(),score,null,null));}catch(NumberFormatException e){errors.add(new ImportRowError(r+1,studentNo,entry.getValue().getCode(),"成绩必须为数字"));}catch(IllegalArgumentException e){errors.add(new ImportRowError(r+1,studentNo,entry.getValue().getCode(),e.getMessage()));}}
   }
  } catch(IllegalArgumentException e){throw e;} catch(Exception e){throw new IllegalArgumentException("Excel解析失败，请使用系统模板",e);}
  if(!valid.isEmpty()) saveItems(id,new ItemsCommand(valid,null),actor); audit.log(actor,"EDU_GRADEBOOK_IMPORT","gradebookId="+id+",rows="+total+",imported="+valid.size()+",errors="+errors.size()); return new ImportResult(total,valid.size(),errors);
 }
 @Transactional public CorrectionResponse requestCorrection(String id, CorrectionCommand command, String actor) {
  Gradebook g=authorizedGradebook(id,actor); if(!"PUBLISHED".equals(g.getStatus())) throw new IllegalStateException("仅已发布成绩可申请更正");
  if(command==null||command.items()==null||command.items().isEmpty()||command.reason()==null||command.reason().isBlank()) throw new IllegalArgumentException("更正项目和原因不能为空");
  int base=courseGrades.findByGradebookIdOrderByVersionNoDesc(id).stream().findFirst().map(CourseGrade::getVersionNo).orElseThrow();
  validateCorrectionItems(id,command.items()); GradeCorrection correction=new GradeCorrection(); correction.setGradebookId(id); correction.setBaseVersion(base); correction.setTargetVersion(base+1); correction.setCorrectionJson(writeJson(command.items())); correction.setStatus("PENDING"); correction.setRequestedBy(actor); correction.setReason(command.reason()); correction=corrections.save(correction); audit.log(actor,"EDU_GRADE_CORRECTION_REQUEST","gradebookId="+id+",correctionId="+correction.getId()); return correctionResponse(correction);
 }
 @Transactional public CorrectionResponse publishCorrection(String correctionId,String actor) {
  GradeCorrection correction=corrections.findById(correctionId).orElseThrow(()->new IllegalArgumentException("更正申请不存在")); if(!"PENDING".equals(correction.getStatus())) throw new IllegalStateException("更正申请不可发布");
  Gradebook g=gradebooks.findById(correction.getGradebookId()).orElseThrow(); if(!"PUBLISHED".equals(g.getStatus())) throw new IllegalStateException("成绩册已不再是已发布状态"); int latest=courseGrades.findByGradebookIdOrderByVersionNoDesc(g.getId()).stream().findFirst().map(CourseGrade::getVersionNo).orElse(0); if(latest!=correction.getBaseVersion()) throw new IllegalStateException("成绩版本已变化，请重新申请更正");
  List<CorrectionItemCommand> changes=readCorrectionItems(correction.getCorrectionJson()); Map<String,CourseGrade> grades=courseGrades.findByGradebookIdAndVersionNo(g.getId(),latest).stream().collect(Collectors.toMap(CourseGrade::getStudentId,x->x)); String previousHash=snapshots.findByGradebookIdOrderByVersionNoDesc(g.getId()).stream().findFirst().map(GradePublishSnapshot::getSnapshotHash).orElse(""); String correctionSnapshot=writeJson(Map.of("baseVersion",latest,"baseSnapshotHash",previousHash,"correctionId",correctionId,"items",changes)); String newHash=hash(correctionSnapshot); for(CorrectionItemCommand change:changes){CourseGrade old=grades.get(change.studentId()); if(old==null) throw new IllegalArgumentException("更正学生不在已发布版本"); GradeItem item=items.findByGradebookId(g.getId()).stream().filter(x->x.getStudentId().equals(change.studentId())&&x.getComponentId().equals(change.componentId())).findFirst().orElseThrow(()->new IllegalArgumentException("更正成绩项目不存在")); AssessmentComponent component=components.findById(change.componentId()).orElseThrow(); BigDecimal oldScore=item.getConvertedScore()==null?BigDecimal.ZERO:item.getConvertedScore(); BigDecimal next=old.getTotalScore().subtract(oldScore.divide(component.getMaxScore(),8,java.math.RoundingMode.HALF_UP).multiply(component.getWeight())).add(change.correctedScore().divide(component.getMaxScore(),8,java.math.RoundingMode.HALF_UP).multiply(component.getWeight())); CourseGrade nextGrade=new CourseGrade(); nextGrade.setGradebookId(g.getId()); nextGrade.setStudentId(old.getStudentId()); nextGrade.setTotalScore(next); nextGrade.setPassed(next.compareTo(schemes.findById(g.getSchemeId()).orElseThrow().getPassScore())>=0); nextGrade.setVersionNo(correction.getTargetVersion()); nextGrade.setSnapshotHash(newHash); courseGrades.save(nextGrade);}
  GradePublishSnapshot snapshot=new GradePublishSnapshot(); snapshot.setGradebookId(g.getId()); snapshot.setVersionNo(correction.getTargetVersion()); snapshot.setSnapshotJson(correctionSnapshot); snapshot.setSnapshotHash(newHash); snapshot.setPublishedBy(actor); snapshot.setPublishedAt(LocalDateTime.now()); snapshots.save(snapshot); correction.setStatus("PUBLISHED"); correction.setPublishedBy(actor); corrections.save(correction); audit.log(actor,"EDU_GRADE_CORRECTION_PUBLISH","gradebookId="+g.getId()+",correctionId="+correctionId+",version="+correction.getTargetVersion()); return correctionResponse(correction);
 }
 private void validateCorrectionItems(String id,List<CorrectionItemCommand> changes){Set<String> keys=new HashSet<>(); Map<String,AssessmentComponent> allowed=components.findBySchemeIdOrderBySortOrder(gradebooks.findById(id).orElseThrow().getSchemeId()).stream().collect(Collectors.toMap(AssessmentComponent::getId,x->x)); Set<String> roster=students.findByGradebookId(id).stream().map(GradebookStudent::getStudentId).collect(Collectors.toSet()); for(CorrectionItemCommand c:changes){AssessmentComponent component=allowed.get(c.componentId()); if(component==null||!roster.contains(c.studentId())) throw new IllegalArgumentException("更正项目或学生不属于当前成绩册"); if(c.correctedScore()==null||c.correctedScore().signum()<0||c.correctedScore().compareTo(component.getMaxScore())>0) throw new IllegalArgumentException("更正成绩超出满分"); if(!keys.add(c.studentId()+"|"+c.componentId())) throw new IllegalArgumentException("更正项目重复");}}
 private String writeJson(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException("更正内容序列化失败",e);}}
 private List<CorrectionItemCommand> readCorrectionItems(String value){try{return json.readValue(value,json.getTypeFactory().constructCollectionType(List.class,CorrectionItemCommand.class));}catch(Exception e){throw new IllegalStateException("更正内容读取失败",e);}}
 private CorrectionResponse correctionResponse(GradeCorrection c){return new CorrectionResponse(c.getId(),c.getGradebookId(),c.getBaseVersion(),c.getTargetVersion(),c.getStatus(),c.getRequestedBy(),c.getPublishedBy(),c.getReason());}
 private CourseOffering authorizedOffering(String id,String actor){CourseOffering offering=offerings.findById(id).orElseThrow(()->new IllegalArgumentException("课程开设不存在"));if(!dataScopes.resolve(actor).teacherIds().contains(offering.getTeacherId()))throw new AccessDeniedException("无权访问该课程开设");return offering;}
 private Gradebook authorizedGradebook(String id,String actor){Gradebook gradebook=gradebooks.findById(id).orElseThrow(()->new IllegalArgumentException("成绩册不存在"));if(!dataScopes.resolve(actor).teacherIds().contains(gradebook.getTeacherId()))throw new AccessDeniedException("无权访问该成绩册");return gradebook;}
 private String serverSchoolId(String actor){return dataScopes.resolve(actor).campusIds().stream().findFirst().orElse("DEFAULT");}
 private void validateScheme(SchemeCommand c){if(c==null||c.components()==null||c.components().isEmpty())throw new IllegalArgumentException("至少配置一个成绩项目");if(c.totalScore()==null||c.totalScore().signum()<=0||c.passScore()==null||c.passScore().signum()<0||c.passScore().compareTo(c.totalScore())>0)throw new IllegalArgumentException("分数范围无效");for(ComponentCommand x:c.components())if(!"MANUAL".equals(x.sourceType()))throw new IllegalArgumentException("第一片只支持 MANUAL 成绩项目");validateWeights(c.components().stream().map(x->{AssessmentComponent a=new AssessmentComponent();a.setWeight(x.weight());return a;}).toList());}
 private void validateWeights(List<AssessmentComponent> list){BigDecimal total=list.stream().map(AssessmentComponent::getWeight).reduce(BigDecimal.ZERO,BigDecimal::add);if(total.compareTo(new BigDecimal("100"))!=0)throw new IllegalArgumentException("成绩项目权重合计必须为100");}
 private Map<String,Object> snapshotStudent(GradebookStudent s){Map<String,Object> snapshot=new LinkedHashMap<>();snapshot.put("studentId",s.getStudentId());snapshot.put("studentNo",s.getStudentNo());snapshot.put("studentName",s.getStudentName());snapshot.put("administrativeClassId",s.getAdministrativeClassId());snapshot.put("enrollmentStatus",s.getEnrollmentStatus());snapshot.put("sourceMemberId",s.getSourceMemberId());snapshot.put("enrolledAt",s.getEnrolledAt());snapshot.put("withdrawnAt",s.getWithdrawnAt());return snapshot;}
 private String hash(Object value){try{String text=value instanceof String?(String)value:json.writeValueAsString(value);byte[] b=MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8));StringBuilder out=new StringBuilder();for(byte x:b)out.append(String.format("%02x",x));return out.toString();}catch(Exception e){throw new IllegalStateException("快照哈希失败",e);}}
}
